1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { createMatchLedger, deriveSeed, finalIslandOf, MASTER_SECRET_BYTES, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
4	import { objectiveRules, type LedgerState } from "@pirate-sea-race/simulation/objectives";
5	import { HeadlessClient } from "@pirate-sea-race/test-tools";
6	import { roomOf, tracker } from "./seaDuelSetup.js";
7	
8	/**
9	 * Every system's seed is derived from the match's one private master secret (§3, §16), never from the public match
10	 * code: the ledger's deal and the final island's socket each follow their own keyed derivation of it. The server's
11	 * test-only seam (`MatchTuning.masterSecret`) injects the secret: here one the test sets before each match is
12	 * created. The test-only source layout and final-socket secret are off, so both come from the secret.
13	 */
14	let server: RunningGameServer;
15	let endpoint: string;
16	/** The master secret of the next match created. */
17	let secret: Uint8Array = new Uint8Array(MASTER_SECRET_BYTES);
18	
19	beforeAll(async () => {
20	  server = await startGameServer({
21	    port: 0,
22	    host: "127.0.0.1",
23	    handleSignals: false,
24	    matchTuning: { sourceLayout: undefined, finalSocketSecret: undefined, masterSecret: () => new Uint8Array(secret) },
25	  });
26	  endpoint = `http://127.0.0.1:${server.port}`;
27	});
28	
29	afterAll(async () => {
30	  await server.close();
31	});
32	
33	/** A deal: each source's type, in source order (8 sites over 2 types: one of 70 layouts). */
34	const dealOf = (ledger: LedgerState): string => ledger.sources.map((source) => `${source.id}=${source.type}`).join(" ");
35	const dealFor = (seed: number): string => dealOf(createMatchLedger({ map: seaMap, seed, rules: objectiveRules }));
36	const secretOf = (fill: number) => new Uint8Array(MASTER_SECRET_BYTES).fill(fill);
37	
38	describe("the match's seeds (§3, §16)", () => {
39	  it("derive the ledger's deal and the final island from the room's master secret, per system, and never from the match code", async ({ onTestFinished }) => {
40	    const track = tracker(onTestFinished);
41	    // Two secrets the test first checks deal differently and pick different sockets.
42	    const first = secretOf(1);
43	    let fill = 2;
44	    while (
45	      (dealFor(deriveSeed(secretOf(fill), "ledger")) === dealFor(deriveSeed(first, "ledger")) ||
46	        finalIslandOf(seaMap, deriveSeed(secretOf(fill), "final-socket")).socket === finalIslandOf(seaMap, deriveSeed(first, "final-socket")).socket) &&
47	      fill < 200
48	    ) {
49	      fill++;
50	    }
51	    const second = secretOf(fill);
52	
53	    const open = async (next: Uint8Array) => {
54	      secret = next;
55	      const client = await HeadlessClient.create(endpoint);
56	      track(client);
57	      const room = roomOf(client);
58	      expect(room.ledgerState.sources.every((source) => source.unlocked)).toBe(true);
59	      return { code: client.code, deal: dealOf(room.ledgerState), socket: room.finalIslandChoice.socket, seeds: room.derivedSeeds() };
60	    };
61	
62	    // The same secret: two matches, two different codes, the same deal and the same final island, each the keyed
63	    // derivation of that secret for its own system.
64	    const a = await open(first);
65	    const b = await open(first);
66	    expect(b.code).not.toBe(a.code);
67	    expect(a.deal).toBe(dealFor(deriveSeed(first, "ledger")));
68	    expect(a.socket).toBe(finalIslandOf(seaMap, deriveSeed(first, "final-socket")).socket);
69	    expect(b.deal).toBe(a.deal);
70	    expect(b.socket).toBe(a.socket);
71	    expect(b.seeds).toEqual(a.seeds);
72	    // One seed per system, all different: no raw seed feeds two systems.
