33	
34	/** Puts a full-set holder on the claim tile and has it hold E (as a player does, refreshing the key) until `until`. */
35	function holdClaim(client: HeadlessClient, until: () => boolean, timeoutMs = 15_000): Promise<void> {
36	  return client.holdUntil(HOLD_E, until, timeoutMs);
