42	  it("wins for a full-set holder stopped in the circle holding E for ten seconds, ends its protection, and ignores every input after the win", async ({ onTestFinished }) => {
43	    expectClaimSeats();
44	    const track = tracker(onTestFinished);
45	    // The guest never readies its arena: it forfeits the duel.
46	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { clients: [{}, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
47	    // The host completes its set by stealing the guest's Moon, and comes out of the duel protected.
48	    await collectAt(host, endpoint, dockFor("sun"), "sun");
49	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
