34	const line = (seat: number, change: Partial<ResultLineView> = {}): ResultLineView => ({
35	  seat,
36	  winner: false,
37	  left: false,
38	  rubbingsHeld: 0,
39	  collected: 0,
40	  thefts: 0,
41	  lost: 0,
42	  duelsWon: 0,
43	  duelsLost: 0,
44	  duelsDrawn: 0,
45	  gold: 50,
46	  cachesClaimed: 0,
47	  islandsVisited: 0,
