49	});
50	
51	/** Both players' results screens, once both show one; they are the same. */
52	async function resultsOf(host: HeadlessClient, guest: HeadlessClient, timeoutMs = 25_000) {
53	  for (const client of [host, guest]) await client.waitFor(() => client.results() !== undefined, timeoutMs);
54	  expect(guest.results()).toEqual(host.results());
55	  for (const client of [host, guest]) expect(client.phase).toBe("ended");
56	  return host.results()!;
57	}
58	
59	describe.concurrent("the endings (§2, §12)", () => {
60	  it("ends by a claim: the winner first, and every player's accomplishments", async ({ onTestFinished }) => {
61	    const track = tracker(onTestFinished);
62	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
63	    await collectAt(guest, endpoint, OLD_STONES, "sun");
64	    await collectFullSet(host, endpoint);
65	    await host.placeShip(endpoint, CLAIM_SEAT);
