70	    expect(results.elapsedTicks).toBe(results.tick - controlStart);
71	    expect(results.players).toEqual([
72	      line(host.seat, { winner: true, rubbingsHeld: 2, collected: 2, islandsVisited: 2 }),
73	      line(guest.seat, { rubbingsHeld: 1, collected: 1, islandsVisited: 1 }),
74	    ]);
75	  }, 30_000);
76	
77	  it("ends at the deadline with no winner, counting a duel, its theft and its gold", async ({ onTestFinished }) => {
78	    const track = tracker(onTestFinished);
79	    // The guest never readies its arena: it forfeits the duel.
80	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { clients: [{}, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
81	    await collectAt(host, endpoint, dockFor("sun"), "sun");
82	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
83	    await placePair(endpoint, host, guest);
