86	    host.chooseTheft("moon");
87	    await host.waitFor(() => host.rubbings().join(",") === "sun,moon");
88	    // The loser respawns moored at a dock: that island counts as visited too.
89	    await guest.waitFor(() => guest.status()?.mode === "sea" && guest.ship()!.dock >= 0, 10_000);
90	    const guestIslands = new Set([dockFor("moon").island, seaMap.docks[guest.ship()!.dock]!.island]).size;
91	    const results = await resultsOf(host, guest);
92	    expect(results).toMatchObject({ reason: "deadline", winnerSeat: 0, tick: controlStartOf(host) + MATCH_TICKS, elapsedTicks: MATCH_TICKS });
93	    expect(results.players).toEqual([
94	      line(host.seat, { rubbingsHeld: 2, collected: 1, thefts: 1, duelsWon: 1, gold: 60, islandsVisited: 1 }),
95	      line(guest.seat, { rubbingsHeld: 0, collected: 1, lost: 1, duelsLost: 1, gold: 40, islandsVisited: guestIslands }),
96	    ]);
97	  }, 35_000);
98	
99	  it("lets a claim completing on the deadline tick win", async ({ onTestFinished }) => {
100	    const track = tracker(onTestFinished);
