@@ -55,3 +55,44 @@ export function parseTestSourceLayout(text: string): string[][] | undefined {
   if (islands.some((group) => group.some((type) => !/^[a-z]+$/.test(type)))) return undefined;
   return islands;
 }
+
+/**
+ * Test-only match timings (protocol v7), so a browser scenario can play a whole match in seconds. The dev and test
+ * entry reads them (never the production `main`); they are off unless the variable is set. Comma-separated
+ * `name=ticks` pairs in world ticks (20 a second), any subset of: `ready` (the ready countdown), `protection` (the
+ * departure's spawn protection, which is also the departure's length), `match` (the match's duration: the claim's
+ * deadline and the timer at once), `sectors` and `carriers` (the minute-20 and minute-28 reveals, after control
+ * start). For example `ready=60,protection=20,match=12000`.
+ */
+export const TEST_TIMINGS_ENV = "PIRATE_SEA_RACE_TEST_TIMINGS";
+
+export const TEST_TIMING_NAMES = ["ready", "protection", "match", "sectors", "carriers"] as const;
+export type TestTimingName = (typeof TEST_TIMING_NAMES)[number];
+export type TestTimings = Partial<Record<TestTimingName, number>>;
+
+/** Parses test-only timings, or undefined when a pair is malformed, unknown, repeated or not a positive integer. */
+export function parseTestTimings(text: string): TestTimings | undefined {
+  const timings: TestTimings = {};
+  for (const pair of text.split(",")) {
+    const match = /^\s*([a-z]+)=(\d{1,7})\s*$/.exec(pair);
+    if (match === null) return undefined;
+    const name = match[1] as TestTimingName;
+    const ticks = Number(match[2]);
+    if (!(TEST_TIMING_NAMES as readonly string[]).includes(name) || name in timings || ticks <= 0) return undefined;
+    timings[name] = ticks;
+  }
+  return timings;
+}
+
+/**
+ * Test-only: pins the secret the server picks the final island's socket with (§3), so a browser scenario knows where
+ * to sail. A decimal 32-bit unsigned integer. The dev and test entry reads it; production draws its own.
+ */
+export const TEST_FINAL_SECRET_ENV = "PIRATE_SEA_RACE_TEST_FINAL_SECRET";
+
+/** Parses a pinned final-socket secret, or undefined when it is not a 32-bit unsigned decimal integer. */
+export function parseTestFinalSecret(text: string): number | undefined {
+  if (!/^\d{1,10}$/.test(text.trim())) return undefined;
+  const secret = Number(text.trim());
+  return secret <= 0xffffffff ? secret : undefined;
+}
