@@ -39,6 +39,40 @@ export async function joinMatch(page: Page, code: string): Promise<void> {
   await expect(page.getByTestId("hud-status")).toHaveText("connected");
 }

+/**
+ * The pinned final-socket secret of the browser server (`PIRATE_SEA_RACE_TEST_FINAL_SECRET` in the Playwright config),
+ * so a scenario knows where the final island is.
+ */
+export const FINAL_SECRET = 3;
+
+/**
+ * Starts a match through its lobby, as players do (§2): the host clicks Start, every page shows the ready countdown,
+ * then the running timer once control starts; the departure's short protection (test-only, 1 s) runs out.
+ */
+export async function startMatch(host: Page, ...others: Page[]): Promise<void> {
+  const start = host.getByRole("button", { name: "Start match" });
+  await expect(start).toBeEnabled();
+  await start.click();
+  for (const page of [host, ...others]) {
+    await expect(page.getByTestId("match-timer")).toHaveAttribute("data-state", "running", { timeout: 15_000 });
+    await expect(page.getByTestId("lobby")).toBeHidden();
+  }
+  for (const page of [host, ...others]) await expect(page.getByTestId("hud-protection")).toHaveAttribute("data-state", "none", { timeout: 5000 });
+}
+
+/**
+ * A lone player's match needs a second player to start (§2: private matches start with two). A companion joins from
+ * its own browser context and stays at its spawn slot; the host starts. Close the returned context when done.
+ */
+export async function startWithCompanion(browser: Browser, host: Page, code: string): Promise<BrowserContext> {
+  const context = await browser.newContext();
+  const companion = await context.newPage();
+  await joinMatch(companion, code);
+  await expect(host.getByTestId("hud-players")).toHaveText("2");
+  await startMatch(host, companion);
+  return context;
+}
+
 export async function selfId(page: Page): Promise<string> {
   return (await page.getByTestId("hud-self").textContent())!;
 }
